def approve_existing_devices(apps, schema_editor):
    """Devices that existed before approval flow were implicitly trusted."""
    FingerPrintID = apps.get_model("users", "FingerPrintID")
    FingerPrintID.objects.update(status="approved")


def dedupe_devices(apps, schema_editor):
    """Keep the oldest row for each (user, unique_id); delete the rest."""
    FingerPrintID = apps.get_model("users", "FingerPrintID")
    seen = set()
    stale = []
    for pk, user_id, unique_id in FingerPrintID.objects.order_by("created_at", "pk").values_list("pk", "user_id", "unique_id"):
        key = (user_id, unique_id)
        if key in seen:
            stale.append(pk)
        else:
            seen.add(key)
    if stale:
        FingerPrintID.objects.filter(pk__in=stale).delete()


